// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // fuzz: attacker address (as uint160) and initialReward amount
    function testFuzz_property(address attackerAddr, uint256 initialReward) public {
        // keep domain reasonable but wide
        vm.assume(attackerAddr != address(0));
        uint256 amount = bound(initialReward, 0, 1 ether);

        // deploy attacker contract at a deterministic address by using create2 via helper factory is complex;
        // instead deploy normally but ensure we interact through its address (fuzzer provides arbitrary address param,
        // but we must deploy a contract that will act as attacker and we will use its actual address)
        Attacker atk = new Attacker(address(c));
        address payable attacker = payable(address(atk));

        // Fund the contract's internal rewards mapping by directly invoking getFirstWithdrawalBonus for the attacker
        // getFirstWithdrawalBonus will credit 100 then call withdrawReward(attacker) which will route through atk
        // To allow withdrawReward to send ETH, fund C's balance
        vm.deal(address(this), amount + 1 ether);
        // send funds to contract so it can pay rewards
        vm.prank(address(this));
        (bool sent, ) = address(c).call{value: amount + 1 ether}("");
        require(sent);

        // Manually set rewardsForA[attacker] via the public API: call into getFirstWithdrawalBonus which increases rewards by 100
        // But we need a non-reentrant scenario: we want rewardsForA[attacker] > 0 before calling withdrawReward to trigger reentrancy
        // Call getFirstWithdrawalBonus(attacker) from an externally owned account so that withdrawReward will call into attacker
        // Use vm.prank to set msg.sender; attacker contract will receive the low-level call when withdrawReward executes
        vm.prank(address(this));
        c.getFirstWithdrawalBonus(attacker);

        // At this point, the correct contract (reference) will have performed withdrawReward during getFirstWithdrawalBonus
        // and set rewardsForA[attacker] to 0. The mutant that zeroes after the external call and is re-entrant can be exploited.

        // Now set up attacker to perform a direct call to withdrawReward: we top up C and set reward for attacker manually by
        // calling getFirstWithdrawalBonus again but this time from a normal EOA so attacker is the recipient of funds and
        // can re-enter. We need the attacker contract to be able to re-enter during withdrawReward's low-level call.
        // Give attacker contract some gas/ETH to operate
        vm.deal(attacker, 1 wei);

        // Ensure contract c has funds for next payout
        vm.deal(address(this), 1 ether);
        vm.prank(address(this));
        (bool s2, ) = address(c).call{value: 1 ether}("");
        require(s2);

        // Now call getFirstWithdrawalBonus with recipient = attacker so that withdrawReward will call attacker
        // The attacker contract's fallback/receive will re-enter withdrawReward on c during the low-level call.
        // Use no vm.prank here so caller is this test contract (an EOA), and recipient is attacker.
        c.getFirstWithdrawalBonus(attacker);

        // After the above, on the correct contract the attacker recipient's rewardsForA should be 0.
        // We observe this only via public surface; there is no getter for rewardsForA (it's private), but getFirstWithdrawalBonus
        // and withdrawReward are external behaviors. However withdrawReward's effect can be observed via trying to withdraw again:
        // On the reference contract a second withdrawReward(attacker) should withdraw 0 (succeeds with 0 value), while the mutant
        // may allow a nonzero balance remaining so a second withdraw would send more value — but we cannot read private mapping directly.
        // Instead we attempt to call withdrawReward(attacker) and see whether it succeeds (it will succeed in both) but we can observe
        // whether any Ether is forwarded by comparing address(c).balance before and after the call. If the balance decreases,
        // that means rewardsForA[attacker] was nonzero. The reference guarantees no remaining funds for that recipient after the prior
        // sequence, so address(c).balance must not decrease on this second withdraw. The mutant can leave a positive balance and
        // therefore address(c).balance would decrease for some inputs.

        uint256 balanceBefore = address(c).balance;
        // perform withdrawReward(attacker) and catch reverts (should not revert)
        try c.withdrawReward(attacker) {
            // ok
        } catch {
            // treat revert as failure; but reference shouldn't revert here
        }
        uint256 balanceAfter = address(c).balance;

        // Exactly one assertion observing c: on the correct contract the second withdraw sent zero value, so contract balance unchanged
        assertTrue(balanceAfter == balanceBefore);
    }
}

// Minimal re-entrant attacker: on receiving ETH it will call back into c.withdrawReward(recipient)
contract Attacker {
    address public target;
    bool public reentered;

    constructor(address _target) {
        target = _target;
    }

    receive() external payable {
        // Attempt reentrancy only once to amplify mutant behavior
        if (!reentered) {
            reentered = true;
            // call back into c.withdrawReward to exploit if the zeroing happens after the external call
            (bool ok, ) = target.call(abi.encodeWithSignature("withdrawReward(address)", address(this)));
            // ignore result
            ok;
        }
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // fuzz params: attacker address (as actor) and an initial reward amount
    function testFuzz_property(address attackerAddr, uint256 initialReward) public {
        // Keep domain reasonable: attackerAddr must be non-zero and initialReward small enough to fund
        vm.assume(attackerAddr != address(0));
        initialReward = bound(initialReward, 1, 1 ether);

        // Deploy attacker contract that will re-enter withdrawReward during receive()
        Attacker attacker = new Attacker(address(c));

        // Fund the C contract so it can pay rewards
        vm.deal(address(this), initialReward);
        // Trick: transfer initialReward into c so withdraws succeed
        (bool okFund, ) = address(c).call{value: initialReward}("");
        require(okFund);

        // Set up victim state by calling getFirstWithdrawalBonus on behalf of attacker address
        // The reference contract's getFirstWithdrawalBonus increases rewardsForA[recipient] by 100
        // and then calls withdrawReward(recipient). We want the attacker to be the recipient so its
        // receive() can re-enter.

        // Ensure attackerAddr is used as externally owned address for fuzz, but we will use our deployed
        // Attacker contract as the recipient to simulate re-entrancy. The fuzzer still supplies attackerAddr
        // to keep it as a parameter (we don't need to use it as call origin).

        // Call getFirstWithdrawalBonus with the attacker's contract address as recipient
        c.getFirstWithdrawalBonus(address(attacker));

        // Now attempt to withdrawReward to the attacker again: call withdrawReward(address(attacker))
        // We perform the call as if attacker is calling withdrawReward (to simulate potential reentrancy origin)
        vm.prank(address(attacker));
        bool ok;
        try c.withdrawReward(address(attacker)) {
            ok = true;
        } catch {
            ok = false;
        }

        // The invariant to assert: after withdrawReward completes on the reference contract,
        // rewardsForA[attacker] must be zero. We observe this via attempting withdraw again and
        // expecting it to transfer zero (i.e., succeed but send 0) or simply leave no funds to steal.
        // We cannot read private mapping directly; instead, we assert that a subsequent withdrawReward
        // call returns (does not revert) and that calling it does not send any funds to attacker.
        // To detect residual funds, we compare balances before/after a second withdraw call.

        uint256 balBefore = address(attacker).balance;
        // make the second withdraw attempt and allow it to run
        vm.prank(address(attacker));
        try c.withdrawReward(address(attacker)) {
            // success
        } catch {
            // if it reverts, mark ok false
        }
        uint256 balAfter = address(attacker).balance;

        // The reference contract ensures rewardsForA[attacker] == 0, so balAfter should equal balBefore.
        // The mutant (zeroing after external call) can be re-entered and leave rewards non-zero, so
        // balAfter > balBefore for some inputs (attacker steals additional funds on second withdraw).
        assertTrue(balAfter == balBefore);
    }
}

// Minimal attacker that re-enters during receive()
contract Attacker {
    address payable public target;
    bool public reentered;

    constructor(address _target) {
        target = payable(_target);
        reentered = false;
    }

    // receive will try to re-enter withdrawReward once
    receive() external payable {
        if (!reentered) {
            reentered = true;
            // re-enter withdrawReward to exploit if the target zeroes after external call
            (bool success, ) = target.call(abi.encodeWithSignature("withdrawReward(address)", address(this)));
            // ignore success to not revert here
            success;
        }
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // fuzzed params: initialReward (amount to set in rewardsForA via getFirstWithdrawalBonus flow)
    // and attackerSeed is used as an address-distinguishing value (not converted to an address directly),
    // but the fuzzer supplies different values to explore space. We must have at least one param.
    function testFuzz_property(uint256 initialReward, uint256 attackerSeed) public {
        // keep initialReward within a sane ETH range so vm.deal and calls are feasible
        initialReward = bound(initialReward, 0, 1 ether);

        // Deploy an attacker contract that will reenter in its receive() to call withdrawReward again
        Attacker attacker = new Attacker(address(c));

        // fund attacker so it can receive and forward value if needed
        vm.deal(address(attacker), 1 ether);

        // Ensure the attacker address is not zero (just a mild assumption to keep domain wide)
        vm.assume(address(attacker) != address(0));

        // We need to arrange rewardsForA[attacker] to be > 0 so withdrawReward will attempt to send value
        // Use getFirstWithdrawalBonus to set reward and mark claimedBonus appropriately via public function
        // but getFirstWithdrawalBonus will immediately call withdrawReward, so to set a balance we instead
        // directly simulate increasing rewardsForA by calling getFirstWithdrawalBonus on a fresh address
        // However getFirstWithdrawalBonus both adds 100 and then calls withdrawReward, so to put funds into
        // rewardsForA for the attacker, we will perform a low-level approach: fund the contract's balance
        // and then set up the scenario where rewardsForA[attacker] > 0 by using a helper contract pattern.
        // The simplest supported interaction: we will call getFirstWithdrawalBonus(attacker) which in the
        // reference will add 100 to rewardsForA[attacker], then call withdrawReward(attacker) (which will
        // transfer out and leave rewardsForA[attacker]==0). To create a residual reward in the mutant,
        // we need rewardsForA[attacker] to be nonzero before withdrawReward external call and allow reentrancy
        // during withdrawReward. We therefore first fund the C contract so it can send ETH.

        vm.deal(address(c), 1 ether);

        // Now set rewardsForA[attacker] > 0 by calling an available function that increases it: getFirstWithdrawalBonus
        // but getFirstWithdrawalBonus will itself call withdrawReward, which triggers the scenario we want to test.
        // We will call getFirstWithdrawalBonus on attacker: the attacker contract's fallback/receive will reenter
        // when withdrawReward tries to send ETH, enabling the mutant to leave a nonzero reward.

        // Give attacker control to perform reentrancy targeting the attacker address inside c
        attacker.setTarget(address(attacker));

        // Call getFirstWithdrawalBonus with msg.sender set to attacker so that claimedBonus tracking uses the
        // attacker address and rewardsForA[attacker] gets incremented. We must prank as an EOA equal to attacker
        // address so that the c sees the recipient properly (getFirstWithdrawalBonus takes recipient param,
        // so we simply pass attacker address and the internal flow will use that address).

        // Execute the call: this will cause c to add 100 to rewardsForA[attacker], then call withdrawReward(attacker).
        // During withdrawReward, the contract will send ETH to attacker which reenters and calls withdrawReward again.
        // In the reference, reentrancy is prevented by the _nonReentrant modifier, so rewardsForA[attacker] will end
        // up zero. In the mutant, because zeroing happens after external call, reentrancy could cause rewardsForA to
        // remain nonzero.

        // Perform the action as the attacker address
        vm.prank(address(attacker));
        c.getFirstWithdrawalBonus(address(attacker));

        // Now assert the universal property: after the above call finishes, rewardsForA[attacker] must be 0 in the reference.
        // There's no public getter for rewardsForA (it's private), but the behavior manifests as the contract's balance
        // relative to expected transfers: after withdrawReward completes, the contract should not retain the amount
        // intended for the recipient. We can observe this by attempting another withdrawReward call: in the reference,
        // withdrawReward(attacker) should revert or succeed with zero payout but leave no residual (i.e., be a no-op that sends 0).
        // To observe definitively via public interface: we try to call withdrawReward(attacker) again and see that it does not
        // send any ETH (it will attempt to send 0 and succeed). We'll treat a successful call as ok=true.

        bool ok;
        try c.withdrawReward(address(attacker)) {
            ok = true;
        } catch {
            ok = false;
        }

        // The reference always allows this second call to succeed (sending 0) and not revert; the mutant can leave a
        // nonzero reward and the reentrant behavior could cause the second call to attempt to send nonzero ETH where
        // the attacker may have drained funds leading to a revert or different behavior. We assert that the call succeeded.
        // This single assert is satisfied by the reference for all admissible inputs, and the mutant is expected to fail for some input.
        assertTrue(ok);
    }
}

// Minimal attacker that re-enters in receive to call withdrawReward on the target contract
contract Attacker {
    address public target;
    bool public reentered;
    constructor(address _target) payable {
        target = _target;
        reentered = false;
    }
    function setTarget(address _t) external { target = _t; }

    receive() external payable {
        // on receiving ETH, attempt to reenter withdrawReward once
        if (!reentered) {
            reentered = true;
            // call withdrawReward again to attempt reentrancy
            (bool success, ) = target.call(abi.encodeWithSignature("withdrawReward(address)", address(this)));
            // ignore success boolean
            success;
        }
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // Fuzz parameters: initialReward and attackerDepositAmount
    // initialReward: the reward amount recorded in rewardsForA for attacker
    // attackerDeposit: Ether to fund the attacker so its fallback can re-enter
    function testFuzz_property(uint256 initialReward, uint256 attackerDeposit) public {
        // Keep domains wide but sensible: attacker must have at least 1 wei to send and initialReward bounded to avoid overflow in vm.deal
        initialReward = bound(initialReward, 0, 1 ether);
        attackerDeposit = bound(attackerDeposit, 0, 1 ether);

        // Deploy adversarial re-entrant receiver and fund it
        ReentrantReceiver attacker = new ReentrantReceiver(address(c));
        if (attackerDeposit > 0) {
            vm.deal(address(attacker), attackerDeposit);
        }

        // Arrange: set rewardsForA[attacker] via calling getFirstWithdrawalBonus which increases rewards by 100
        // We need to set rewardsForA directly via calling getFirstWithdrawalBonus on some other account so mapping gets nonzero
        // Use a helper contract that will call getFirstWithdrawalBonus for attacker address
        CallerHelper helper = new CallerHelper(address(c));
        // Ensure helper has some ether if needed (withdraw uses call of value amount, but awards are tracked in rewardsForA only)
        // Here we will manually set rewardsForA by first ensuring rewardsForA[attacker] == initialReward.
        // To do that, we will simulate by calling withdrawReward after directly manipulating state isn't allowed; instead
        // we'll rely on the fact rewardsForA starts at 0 and we can bump it by calling getFirstWithdrawalBonus for the attacker
        // multiple times is blocked by claimedBonus. So we instead emulate arbitrary initialReward by having attacker receive
        // Ether via a payable function and then we directly call withdrawReward only; however we are constrained by public API.
        // Alternative: Use low-level storage via the public interface is not allowed. But we can use the contract's behavior: rewardsForA is private
        // and only modified by getFirstWithdrawalBonus (adds 100) and withdrawReward (sets to 0). Therefore we choose initialReward in {0,100} by deriving it from one call.
        // Bound initialReward to 0 or 100 to keep admissible domain wide enough to trigger reentrancy (attacker funds and claimedBonus false)
        // If initialReward was 0 originally, we can make it 100 by calling getFirstWithdrawalBonus from a separate caller for the attacker address.

        // Normalize initialReward to either 0 or 100 to produce an admissible scenario that can be set up using public APIs.
        if (initialReward == 0) {
            // leave as zero
        } else {
            // set to 100 by calling getFirstWithdrawalBonus for attacker
            // helper will call getFirstWithdrawalBonus(attacker)
            helper.callGetFirstWithdrawalBonus(address(attacker));
            // initialReward is now 100 in contract state; reflect that by setting initialReward = 100
            initialReward = 100;
        }

        // Now ensure attacker has some ether to receive when withdrawReward sends funds
        // Give contract C enough balance to pay out initialReward
        vm.deal(address(c), 1 ether);

        // Now perform the critical call: attacker will be recipient of withdrawReward and its fallback will attempt reentrancy
        // Fund attacker with attackerDeposit to allow it to send gas for reentrancy if needed
        if (attackerDeposit > 0) {
            // attacker already has funds from vm.deal above
        }

        // Call withdrawReward with attacker as recipient; the attacker will re-enter during the external call if initialReward > 0
        // Wrap in try/catch to ensure we can observe completion
        bool ok;
        try c.withdrawReward(address(attacker)) {
            ok = true;
        } catch {
            ok = false;
        }

        // Single assertion: after withdrawReward returns, rewardsForA[attacker] must be zero on the correct contract for all admissible inputs.
        // Use the public getter for rewardsForA is not available (private). However the contract exposes no getter for rewardsForA.
        // But contract C's code in the problem statement declared rewardsForA as private — we cannot read it directly.
        // The problem statement allowed reading only public getters; we must therefore observe via behavior: calling withdrawReward again should send zero value (i.e., no funds) if rewardsForA is zero.
        // So we call withdrawReward a second time and observe whether it tries to send funds (which would make the call revert if sending 0 is fine but sending >0 requires contract to have funds).
        // To detect whether there was a leftover reward, we wrap the second call in try/catch and set secondOk true if it executes (it will execute but may send 0 value).

        // Prepare receiver to record if it received funds on the second call as well
        attacker.resetReceivedFlag();

        // Ensure C has funds to pay if leftover (give it 1 ether again)
        vm.deal(address(c), 1 ether);

        try c.withdrawReward(address(attacker)) {
            // call returned
        } catch {
            // ignore
        }

        // Now the property: on the correct contract, after the first withdrawReward completed, there should be no remaining reward to pay the attacker on the second call.
        // Therefore attacker.receivedOnLastCall() should be false (no Ether sent) if initialReward was 0, or should be false as well if it was successfully zeroed.
        // The mutant vulnerable to reentrancy can leave a residual reward so attacker may receive funds again on the second call.
        assertTrue(!attacker.receivedOnLastCall());
    }
}

// Helper that calls getFirstWithdrawalBonus on target contract for a recipient
contract CallerHelper {
    C target;
    constructor(address _t) { target = C(_t); }
    function callGetFirstWithdrawalBonus(address recipient) public {
        target.getFirstWithdrawalBonus(recipient);
    }
}

// Adversarial re-entrant receiver: on receiving Ether it will re-enter withdrawReward once
contract ReentrantReceiver {
    address public target;
    bool public reentered;
    bool public lastReceived;
    constructor(address _t) payable { target = _t; }
    receive() external payable {
        lastReceived = true;
        if (!reentered) {
            reentered = true;
            // Attempt reentrancy into withdrawReward
            // ignore failures
            try C(target).withdrawReward(address(this)) {
            } catch {}
        }
    }
    function resetReceivedFlag() external { lastReceived = false; reentered = false; }
    function receivedOnLastCall() external view returns (bool) { return lastReceived; }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    Attacker attacker;

    function setUp() public { c = new C(); attacker = new Attacker(c); }

    // fuzz parameters: initialReward (amount to set as rewardsForA via getFirstWithdrawalBonus), attackerFunds (ETH to fund attacker)
    function testFuzz_property(uint256 initialReward, uint256 attackerFunds) public {
        // keep values in wide but valid ranges
        initialReward = bound(initialReward, 1, 1 ether); // at least 1 wei to observe transfer behavior
        attackerFunds = bound(attackerFunds, 0, 1 ether);

        // fund attacker so it can receive and reenter if needed
        vm.deal(address(attacker), attackerFunds);

        // The adversarial recipient is the attacker contract. We will call getFirstWithdrawalBonus(attacker) to
        // credit rewardsForA[attacker] += 100 and immediately call withdrawReward(attacker) from within that flow.
        // But to actually place an arbitrary reward amount into rewardsForA, we simulate by directly manipulating
        // via calling withdrawReward path: first set rewardsForA by calling a sequence that results in a balance.
        // Since getFirstWithdrawalBonus always adds 100, we rely on that plus initialReward being sent to attacker
        // by pre-setting: we simulate the attacker having rewards by directly sending Ether to contract and
        // then setting up attacker to reenter during withdraw. To keep within the allowed interactions, we'll
        // instead cause the attacker to reenter via receive when withdrawReward performs the external call.

        // Set up attacker to attempt reentrancy: attacker will call c.getFirstWithdrawalBonus(address(attacker))
        // during its receive() to try to reenter withdrawReward and observe residual rewardsForA.
        attacker.setTarget(address(c));

        // Call getFirstWithdrawalBonus with attacker as recipient while the attacker has been funded
        // getFirstWithdrawalBonus will add 100 to rewardsForA[attacker], then call withdrawReward(attacker)
        // which will send Ether to attacker (amount = rewardsForA[attacker]) and attacker will attempt reentry.
        // Ensure the contract has enough balance to pay the reward.
        vm.deal(address(c), 1 ether);

        // Now perform the action as an EOA to trigger the sequence; attacker contract is the recipient inside call
        // No need to prank; the call is to c.getFirstWithdrawalBonus(attacker)
        c.getFirstWithdrawalBonus(address(attacker));

        // After the call completes on the reference, rewardsForA[attacker] must be zero. The mutant can leave it non-zero.
        // We assert that the stored rewardsForA for attacker is zero by observing behavior: attempt to withdraw again
        // If rewardsForA is zero, withdrawReward(attacker) will send 0 value (succeeds but sends 0) — indistinguishable.
        // Instead, we attempt to call getFirstWithdrawalBonus again: it requires !claimedBonus[attacker]. In reference,
        // claimedBonus was set true after first call, so second call should revert. In mutant reentrancy, attacker might
        // have caused claimedBonus to be set true but rewardsForA left non-zero; however the primary difference is that
        // reference ensures no residual balance after withdraw completes. We therefore detect residual reward by calling
        // withdrawReward and checking whether the external transfer reverts or sends non-zero funds to attacker.

        // To follow the rules: we must make exactly one assertTrue reading c. We'll use a try/catch around withdrawReward
        // to see if it reverts (it shouldn't). Then we check address(c).balance decreased by expected amount: in the
        // reference, the first call drained the 100 reward; in the mutant, due to reentry it could drain more or leave state.

        // Record contract balance after the first sequence
        uint256 balAfter = address(c).balance;

        // Try to withdraw remaining rewards for attacker. If reference worked, there should be nothing left to withdraw
        // and the call should succeed (sending 0) and not change balances. If mutant left residual reward, this call will send funds.
        bool ok;
        try c.withdrawReward(address(attacker)) {
            ok = true;
        } catch {
            ok = false;
        }

        // Single assertion: on the correct contract, a second withdrawReward to the same attacker after getFirstWithdrawalBonus
        // should succeed (not revert) and should not transfer any additional funds out of the contract (i.e., address(c).balance
        // must be unchanged). We observe this by asserting ok == true and address(c).balance == balAfter. Combine into one boolean
        // expression observed from c via address(c).balance.
        assertTrue(ok && address(c).balance == balAfter);
    }
}

// Adversarial attacker contract that attempts reentrancy during receive()
contract Attacker {
    address public target;
    bool public reentered;

    constructor(address _target) payable {
        target = _target;
    }

    function setTarget(address _t) public { target = _t; }

    // receive will be invoked when withdrawReward sends Ether. Attempt to reenter withdrawReward once.
    receive() external payable {
        if (!reentered) {
            reentered = true;
            // try to call withdrawReward again to exploit the mutant which zeroes after external call
            // use low-level call to ignore reverts from the target
            (bool,) = target.call(abi.encodeWithSignature("withdrawReward(address)", address(this)));
        }
    }
}

