pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzz parameters: recipient address (the attacker) and a nonzero initial reward amount
    function testFuzz_property(address attackerAddr, uint256 initialReward) public {
        // keep domain wide but meaningful
        vm.assume(attackerAddr != address(0));
        initialReward = bound(initialReward, 1, 1 ether);

        // deploy an attacker contract at the provided address by using prank to fund and then create
        // We cannot force a created contract to have a specific address in general, so we will ignore attackerAddr
        // as an address-to-deploy target, but we still accept it as a fuzz parameter per requirements.
        // Deploy Attacker which will reenter on receive
        Attacker attacker = new Attacker(c);

        // fund C so it can pay out
        vm.deal(address(c), 1 ether);

        // set up state: increase rewardsForA[attacker] via the public function getFirstWithdrawalBonus
        // but getFirstWithdrawalBonus adds 100 and then calls withdrawReward and marks claimedBonus - instead
        // we need to simulate that rewardsForA[attacker] has initialReward; since rewardsForA is private
        // we cannot set it directly. Instead we will rely on the fact that withdrawReward reads rewardsForA[recipient]
        // To place a reward, we will have attacker call a helper function on C via a crafted flow.
        // Because C in src is the reference contract, we cannot modify internals here. However, we can exploit
        // that getFirstWithdrawalBonus increases rewardsForA by 100. To create a larger reward we call it multiple times
        // from different callers to accumulate; but claimedBonus prevents multiple bonuses per recipient. So
        // simpler: we will top up c's balance and directly manipulate rewardsForA is impossible— instead we test
