pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    Reverter r;

    function setUp() public { c = new C(); r = new Reverter(); }

    // Fuzz parameter: any address that will be used as recipient
    function testFuzz_property(address recipient) public {
        // Keep domain wide but avoid zero address to ensure payable calls behave normally
        vm.assume(recipient != address(0));

        // Fund the reverter so that if call forwards value it can accept then revert
        vm.deal(address(r), 1 ether);

        // We will attempt to call getFirstWithdrawalBonus with the reverter as recipient.
        // The helper will revert when receiving funds, causing withdrawReward to revert in the mutant
        // but in the reference contract the whole call also reverts — we detect whether after a call
        // that reverts the claimedBonus getter is set or not. To exercise difference we perform two flows:
        // 1) Call with a benign recipient (an EOA represented by `recipient`) — should succeed and leave claimedBonus true.
        // 2) Call with the adversarial reverter address — the call will revert; we catch the revert and then
        //    call getFirstWithdrawalBonus on the benign recipient again to see whether the contract state
        //    was left inconsistent by earlier revert (mutant behaves differently in some cases).

        // Ensure the fuzzed recipient has some ether so calls from it behave like an EOA
        vm.deal(recipient, 1 ether);

        // 1) Successful flow using fuzzed recipient
        vm.prank(recipient);
        bool ok1;
        try c.getFirstWithdrawalBonus(recipient) {
            ok1 = true;
        } catch {
            ok1 = false;
        }
        // If the call succeeded, the reference guarantees claimedBonus[recipient] == true
        if (ok1) {
            // single assertTrue required by harness: check claimedBonus via autogenerated getter
            // The reference must satisfy this for all inputs; the mutant will fail for some.
            assertTrue(C(address(c)).claimedBonus(recipient));
            return;
        }

        // 2) If first call reverted (unlikely for an EOA), proceed to exercise the adversarial callee
        // Call with the Reverter as recipient to trigger behavior that distinguishes mutant from reference
        bool ok2;
        vm.prank(address(r));
        try c.getFirstWithdrawalBonus(address(r)) {
            ok2 = true;
        } catch {
            ok2 = false;
        }

        // After the failed attempt with adversarial callee, the reference ensures that claimedBonus for that callee remains false
        // (call reverted so state not changed). We assert that claimedBonus for the reverter is false.
        // The mutant can incorrectly mark it true before the external call and thus on revert the state may differ.
        assertTrue(!C(address(c)).claimedBonus(address(r)));
    }
}

contract Reverter {
    receive() external payable {
        revert("fail");
    }
}

