pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzz the recipient (address) which will be the target of the external call
    // Deploy a reverter helper that will revert on receiving funds, to distinguish reference vs mutant
    function testFuzz_property(address recipient) public {
        // keep recipient nonzero to be in wide admissible domain
        vm.assume(recipient != address(0));

        // deploy adversarial callee that reverts on receive
        Reverter rev = new Reverter();

        // we will pass the reverter's address as the recipient to force the external call to hit the callee
        address target = address(rev);

        // fund the contract so it can attempt the withdraw
        vm.deal(address(c), 1 ether);

        // Call getFirstWithdrawalBonus on c and capture whether it returns (ok) or reverts
        bool ok;
        try c.getFirstWithdrawalBonus(target) {
            ok = true;
        } catch {
            ok = false;
        }

        // The reference contract guarantees that when getFirstWithdrawalBonus returns successfully, claimedBonus[target] == true.
        // This single assertion reads c's public getter claimedBonus and is true for the reference; the mutant that sets
        // claimedBonus before withdrawal can cause a revert and thus produce different success behavior; assert that
        // whenever the call succeeded, the getter reports true.
        if (ok) {
            assertTrue(c.claimedBonus(target));
        } else {
            // If the call reverted, we still assert that the call did not return true with claimed false.
            // This branch does not assert anything about c (to keep exactly one assertion over c when ok==true).
            assertTrue(true);
        }
    }
}

// adversarial callee that reverts when receiving funds
contract Reverter {
    receive() external payable {
        revert("revert on receive");
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // drive the contract and check the distinguishing property
    function run(address payable recipient, uint initialEther) public payable {
        // require this test contract holds enough ether to fund the recipient payout simulation
        require(address(this).balance >= initialEther);

        // Fund the target contract so it can pay out rewards if it does withdraw immediately.
        // Send initialEther to the target contract
        (bool s, ) = address(c).call{value: initialEther}("");
        require(s);

        // record contract balance before action
        uint before = address(c).balance;

        // call the function that either withdraws immediately (original) or only marks claimed (mutant)
        c.getFirstWithdrawalBonus(recipient);

        // record contract balance after action
        uint after = address(c).balance;

        // Assert that the contract's balance decreased by at least 100 (means immediate withdrawal happened)
        // This holds on the original P (which calls withdrawReward) and is violated by M (which leaves funds in rewardsForA)
        assert(before - after >= 100);
    }

    // allow receiving ETH for test funding
    receive() external payable {}
}

