pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzzed params: recipient (address) and initialFunding (uint256)
    function testFuzz_property(address recipient, uint256 initialFunding) public {
        // keep funding reasonable but wide
        initialFunding = bound(initialFunding, 0, 1 ether);

        // fund the recipient EOA so it can receive ETH if withdraw happens
        vm.deal(recipient, 0);

        // fund the contract with some Ether so that withdraw can succeed if it tries to send
        // also ensure contract has at least 100 wei so withdraw can transfer 100 when present
        uint256 fundForContract = 100 wei + initialFunding;
        vm.deal(address(this), fundForContract);
        payable(address(c)).transfer(fundForContract);

        // record contract balance before the call
        uint256 before = address(c).balance;

        // call getFirstWithdrawalBonus as arbitrary caller; recipient can be any address
        // call must not revert in reference implementation; wrap to capture if it reverts
        bool ok;
        try c.getFirstWithdrawalBonus(recipient) {
            ok = true;
        } catch {
            ok = false;
        }

        // After successful call on reference, the contract should not have kept the bonus amount inside.
        // We assert that if the call succeeded, the contract balance is <= before (it should have decreased by 100),
        // i.e., it did not increase (the mutant that removed withdrawal can increase balance by leaving reward inside).
        // This single assert reads c via address(c).balance.
        if (ok) {
            assertTrue(address(c).balance <= before);
        } else {
            // If the call reverted, the reference contract would also revert for same inputs; assert consistent revert
            // We assert that call reverted (ok == false) only if the call indeed reverted — reading behavior via ok
            assertTrue(ok == false);
        }
    }
}

