contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzzed addr is the recipient; we deploy a Reverter helper and pass its address
    function testFuzz_property(address recipient) public {
        // keep the fuzzed address non-zero to be a sensible recipient
        vm.assume(recipient != address(0));

        // deploy a helper that will revert on plain calls to simulate a recipient that cannot receive ETH
        Reverter rev = new Reverter();

        // Ensure the helper's address is what we pass as recipient to exercise external call behavior
        address badRecipient = address(rev);

        // Now call getFirstWithdrawalBonus on c with the reverting recipient.
        // For the reference contract, getFirstWithdrawalBonus will try to withdraw and that low-level call will revert,
        // causing getFirstWithdrawalBonus to revert as well. For the mutant (where withdrawReward call was removed),
        // the call will succeed and return normally (leaving funds inside c).
        bool ok;
        try c.getFirstWithdrawalBonus(badRecipient) {
            ok = true;
        } catch {
            ok = false;
        }

        // The property: the reference MUST revert (ok == false) for this admissible input; the mutant that removed
        // the withdrawal will instead succeed (ok == true) for that same input. We assert the reference behavior (revert).
        assertTrue(!ok);
    }
}

// adversarial helper that reverts on any call, simulating a recipient that cannot accept ETH
